import {stories,SAMPLE} from './stories.js';
import {DreamAudio,formatTime,clamp} from './audio-engine.js';
import {voiceStore,loadPreferences,savePreferences} from './storage.js';
const $=id=>document.getElementById(id);const prefs=loadPreferences();let current=stories[0],favorites=new Set(Array.isArray(prefs.saved)?prefs.saved:[]),filter='all',page='stories',soundOnly=false,toastTimer;
const voices=new Map();let bundled={};
const engine=new DreamAudio($('sessionAudio'),updatePlayer);
const validSound=['rain','ocean','wind','forest'].includes(prefs.ambience)?prefs.ambience:'rain';
Object.assign(engine.settings,{ambience:validSound,voice:['male','female'].includes(prefs.voice)?prefs.voice:'female',narration:Number.isFinite(prefs.narration)?clamp(prefs.narration):.8,ambient:Number.isFinite(prefs.ambient)?clamp(prefs.ambient):.45,timer:[0,5,15,30,45,60].includes(prefs.timer)?prefs.timer:30,only:typeof prefs.only==='boolean'?prefs.only:true,lock:prefs.lock===true});
engine.title=current.title;
function persist(){if(!savePreferences({...engine.settings,saved:[...favorites],dim:document.body.classList.contains('dimmed')}))toast('Settings could not be saved in this browser.');}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function openDialog(id){$(id).showModal();}
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
function switchPage(target){page=target;for(const el of document.querySelectorAll('.page'))el.hidden=el.id!==`page-${target}`;for(const b of document.querySelectorAll('[data-page]')){b.classList.toggle('active',b.dataset.page===target);if(b.dataset.page===target)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}window.scrollTo({top:0,behavior:'auto'});}
for(const b of document.querySelectorAll('[data-page]'))b.onclick=()=>switchPage(b.dataset.page);
document.querySelector('.brand').onclick=e=>{e.preventDefault();switchPage('stories');};
function renderStories(){
 const matches=s=>filter==='all'||(filter==='forest'&&['cabin','garden'].includes(s.id))||(filter==='coast'&&s.id==='ocean');
 renderCards($('storyGrid'),stories.filter(s=>(filter!=='all'||s.id!=='cabin')&&matches(s)));renderCards($('savedGrid'),stories.filter(s=>favorites.has(s.id)));$('emptySaved').hidden=favorites.size>0;
}
function renderCards(container,list){container.replaceChildren();for(const s of list){const card=document.createElement('article');card.className='story-card';card.innerHTML=`<button class="story-image" aria-label="Open ${s.title}"><img src="assets/${s.image}" alt="Original ${s.title} landscape illustration" loading="lazy"></button><span class="image-tag">${s.eyebrow}</span><h3>${s.title}</h3><button class="save-button ${favorites.has(s.id)?'saved':''}" aria-label="${favorites.has(s.id)?'Unsave':'Save'} ${s.title}" aria-pressed="${favorites.has(s.id)}">${favorites.has(s.id)?'♥':'♡'}</button><p>${s.mood}</p><p class="story-status">${s.status} · narration pending</p><button class="card-read">Read the story ↗</button>`;card.querySelector('.story-image').onclick=()=>selectStory(s);card.querySelector('.card-read').onclick=()=>readStory(s);card.querySelector('.save-button').onclick=()=>{favorites.has(s.id)?favorites.delete(s.id):favorites.add(s.id);persist();renderStories();};container.append(card);}}
for(const b of document.querySelectorAll('[data-filter]'))b.onclick=()=>{filter=b.dataset.filter;for(const f of document.querySelectorAll('[data-filter]'))f.classList.toggle('active',f===b);renderStories();};
function readStory(s){$('readTitle').textContent=s.title;$('readStatus').textContent=s.status.toUpperCase();$('readText').replaceChildren(...s.text.split('\n\n').map(t=>{const p=document.createElement('p');p.textContent=t;return p;}));openDialog('readDialog');}
$('readCabin').onclick=()=>readStory(stories[0]);$('readSample').onclick=()=>readStory(stories[0]);$('readStory').onclick=()=>readStory(current);
$('copySample').onclick=async()=>{try{await navigator.clipboard.writeText(SAMPLE);toast('Original sample script copied.');}catch{readStory(stories[0]);toast('Select and copy the text from the story.');}};
async function activeBlob(){const key=`${current.id}-${engine.settings.voice}`;if(voices.has(key))return voices.get(key);if(bundled[key]){const r=await fetch(bundled[key]);if(!r.ok)throw new Error('The narration file could not load.');const blob=await r.blob();voices.set(key,blob);return blob;}return null;}
async function refreshVoice(){try{const blob=await activeBlob();engine.setStory(blob,`${current.id}-${engine.settings.voice}`);if(!blob&&!engine.settings.only){engine.settings.only=true;toast('Narration is pending for this story. Ambience is ready.');}syncControls();}catch{toast('Narration could not load. Please retry online.');}}
async function selectStory(s,show=true){current=s;soundOnly=false;engine.title=s.title;engine.configure({ambience:s.ambience});await refreshVoice();$('playerArt').src=`assets/${s.image}`;$('playerTitle').textContent=s.title;$('playerDesc').textContent=s.mood;$('miniArtwork').querySelector('img').src=`assets/${s.image}`;$('miniTitle').querySelector('strong').textContent=s.title;updatePlayer(engine.snapshot());if(show)openDialog('playerDialog');}
$('heroPlay').onclick=()=>selectStory(stories[0]);$('miniArtwork').onclick=$('miniTitle').onclick=$('openMixer').onclick=()=>openDialog('playerDialog');
function syncControls(){const s=engine.settings;$('ambienceOnly').checked=s.only;$('narrationVol').value=Math.round(s.narration*100);$('ambienceVol').value=Math.round(s.ambient*100);$('narrationValue').value=`${Math.round(s.narration*100)}%`;$('ambienceValue').value=`${Math.round(s.ambient*100)}%`;$('ambienceSelect').value=s.ambience;$('timerSelect').value=s.timer;$('lockMode').checked=s.lock;for(const b of document.querySelectorAll('[data-voice]')){b.classList.toggle('active',b.dataset.voice===s.voice);b.setAttribute('aria-pressed',b.dataset.voice===s.voice);}persist();}
let lastMessage='Ambience ready. Narration has not been added.';
function updatePlayer(state,message){
 if(message)lastMessage=message;if(!$('mainPlay'))return;
 for(const id of ['mainPlay','miniPlay']){$(id).textContent=state.playing?'Ⅱ':state.loading?'…':'▶';$(id).setAttribute('aria-label',state.playing?'Pause audio':state.loading?'Preparing audio':'Play audio');$(id).disabled=state.loading;}
 $('playStatus').textContent=lastMessage;$('miniTime').textContent=formatTime(state.elapsed);$('elapsed').textContent=formatTime(state.elapsed);
 const length=state.end??(engine.settings.only?null:state.narrationDuration);$('duration').textContent=length?formatTime(length):'∞';$('seek').value=length?clamp(state.elapsed/length)*100:0;$('seek').disabled=!length||state.loading;
 $('miniSub').textContent=state.loading?'Preparing your session…':`${soundNames[engine.settings.ambience]||'Gentle rain'} · ${state.playing?(engine.settings.only?'ambience only':engine.settings.voice+' narrator'):'paused'}`;
 $('timerRemaining').textContent=state.end!==null?`${formatTime(Math.max(0,state.end-state.elapsed))} left · fades gently`:'60-second fade-out';
 const locked=engine.settings.lock&&state.playing;for(const id of ['narrationVol','ambienceVol','timerSelect','ambienceSelect','ambienceOnly','lockMode'])$(id).disabled=locked||state.loading;for(const b of document.querySelectorAll('[data-voice]'))b.disabled=locked||state.loading;
}
async function toggle(){if(engine.playing)engine.pause();else{if(!engine.settings.only&&!engine.narrationBlob){toast('Add a narrator sample first, or choose ambience only.');openDialog('playerDialog');return;}await engine.play();}}
$('mainPlay').onclick=$('miniPlay').onclick=toggle;
$('skipBack').onclick=()=>engine.seek(engine.elapsed()-15);$('skipAhead').onclick=()=>engine.seek(engine.elapsed()+15);
$('seek').onchange=()=>{const length=engine.end??engine.nb?.duration;if(length)engine.seek(length*Number($('seek').value)/100);};
for(const [id,kind,out]of [['narrationVol','narration','narrationValue'],['ambienceVol','ambient','ambienceValue']])$(id).oninput=()=>{engine.setVolume(kind,Number($(id).value)/100);$(out).value=`${$(id).value}%`;persist();};
$('timerSelect').onchange=()=>{const resume=engine.configure({timer:Number($('timerSelect').value)});syncControls();if(resume)engine.play();};
$('lockMode').onchange=()=>{engine.configure({lock:$('lockMode').checked});if(engine.settings.lock&&!engine.settings.timer)engine.settings.timer=30;syncControls();toast(engine.settings.lock?'Press Play to prepare your mix. Keep the app open until audio starts.':'Live mixing selected.');};
$('ambienceSelect').onchange=()=>{const resume=engine.configure({ambience:$('ambienceSelect').value});syncControls();if(resume)engine.play();};
$('ambienceOnly').onchange=async()=>{if(!$('ambienceOnly').checked&&!engine.narrationBlob){$('ambienceOnly').checked=true;toast('This narrator has not been added yet. Visit Your narrators.');return;}const resume=engine.configure({only:$('ambienceOnly').checked});syncControls();if(resume)engine.play();};
for(const b of document.querySelectorAll('[data-voice]'))b.onclick=async()=>{const wasPlaying=engine.playing;engine.configure({voice:b.dataset.voice});await refreshVoice();if(wasPlaying)engine.play();};
const soundNames={rain:'Gentle rain',ocean:'Ocean waves',wind:'Evening wind',forest:'Night forest'};
const soundDescriptions={rain:'Soft rainfall, with a low rumble far beyond the trees.',ocean:'Slow waves finding the shore, then slipping away.',wind:'A soft breeze, rising and settling with the evening.',forest:'Quiet leaves and a delicate chorus of night insects.'};
function renderSounds(){for(const [id,name]of Object.entries(soundNames)){const card=document.createElement('article');card.className='sound-card';card.innerHTML=`<div><span class="sound-icon">${{rain:'☂',ocean:'≋',wind:'〰',forest:'♧'}[id]}</span><h3>${name}</h3><p>${soundDescriptions[id]}</p></div><button class="secondary">Listen to ${name.toLowerCase()} &nbsp; ▶</button>`;card.querySelector('button').onclick=async()=>{await selectStory(stories.find(s=>s.ambience===id)||stories[0],false);soundOnly=true;engine.configure({ambience:id,only:true});engine.title=name;$('playerTitle').textContent=name;$('playerDesc').textContent=soundDescriptions[id];$('miniTitle').querySelector('strong').textContent=name;syncControls();openDialog('playerDialog');engine.play();};$('soundGrid').append(card);}}
function renderVoices(){const container=$('voiceGrid');container.replaceChildren();for(const sex of ['male','female']){const key=`cabin-${sex}`,blob=voices.get(key);const available=!!blob||!!bundled[key];const card=document.createElement('article');card.className='voice-card';card.innerHTML=`<span class="voice-symbol">♩</span><span class="eyebrow"> &nbsp; ${sex.toUpperCase()} NARRATOR</span><h3>${sex==='male'?'Warm & grounded':'Soft & reassuring'}</h3><p>${available?'Sample added · The Rainy Cabin':'Sample pending · no audio generated yet'}</p><button class="secondary sample-play" ${available?'':'disabled'}>${available?'Compare this voice ▶':'Awaiting narration'}</button><label class="secondary upload-label">${available?'Replace audio':'Add narration audio'}<input type="file" accept="audio/*,.mp3,.m4a,.wav" aria-label="Upload ${sex} narration"></label>${blob?'<button class="text-button remove-voice">Remove</button>':''}<p class="small">Private to this device. Add your own recording or your original ElevenLabs sample.</p>`;
 card.querySelector('.sample-play').onclick=async()=>{engine.configure({voice:sex,only:false,lock:false});await selectStory(stories[0],false);engine.configure({only:false});syncControls();openDialog('playerDialog');engine.play();};
 card.querySelector('input').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024){toast('Please use an audio file smaller than 20 MB.');return;}try{const ctx=await engine.context();const buffer=await ctx.decodeAudioData(await file.arrayBuffer());if(buffer.duration>45*60)throw new Error('Please use a recording shorter than 45 minutes.');await voiceStore(key,file);voices.set(key,file);engine.cache.delete(`voice-${key}`);renderVoices();if(current.id==='cabin'&&engine.settings.voice===sex)await refreshVoice();toast('Narration added and saved on this device.');}catch(e){toast(e.message||'Could not save this audio. Try an MP3 file and allow website storage.');}};
 const remove=card.querySelector('.remove-voice');if(remove)remove.onclick=async()=>{try{await voiceStore(key,null);voices.delete(key);engine.cache.delete(`voice-${key}`);renderVoices();if(current.id==='cabin'&&engine.settings.voice===sex)await refreshVoice();toast('Uploaded narration removed.');}catch{toast('Could not remove the recording. Please retry.');}};container.append(card);}}
$('helpBtn').onclick=()=>openDialog('helpDialog');$('nightBtn').onclick=()=>{document.body.classList.toggle('dimmed');$('nightBtn').setAttribute('aria-pressed',document.body.classList.contains('dimmed'));persist();};
if(prefs.dim){document.body.classList.add('dimmed');$('nightBtn').setAttribute('aria-pressed','true');}
async function boot(){try{const r=await fetch('assets/narration.json');if(r.ok)bundled=await r.json();}catch{}try{for(const sex of ['male','female']){const blob=await voiceStore(`cabin-${sex}`);if(blob)voices.set(`cabin-${sex}`,blob);}}catch{}renderVoices();await refreshVoice();updatePlayer(engine.snapshot());if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});}
renderStories();renderSounds();syncControls();boot();
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){engine.tick();updatePlayer(engine.snapshot());}});
